sys_variable_value.value:
(function execute(inputs, outputs) {
    try {
        var api = new trigger_enroll_workflow();
        var sys_id = inputs.ritm_sys_id
        gs.info("Received SYS ID: " + sys_id);
        var result = api.execute(sys_id);
        outputs.status = result;
    } catch (ex) {
        gs.error("Error executing trigger_enroll_workflow for RITM " +
                 inputs.ritm_sys_id + " : " + ex);

        outputs.status = "false";
        outputs.error_message = ex + '';
    }
})(inputs, outputs);

